def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = (value or "").strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"
        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        value = value or ""
        match = re.search(r"x|ext|#", value, flags=re.IGNORECASE)
        if match:
            value = value[:match.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = (value or "").strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value and (value.isupper() or value.islower()):
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    prepared = []
    for index, row in enumerate(rows):
        updated = parse_updated(row["updated"])
        email = normalize_email(row.get("email", ""))
        email = email if valid_email(email) else ""
        phone = normalize_phone(row.get("phone", ""))

        if not email and not phone:
            continue

        opted_out = (row.get("opted_out", "") or "").strip().lower() in {
            "y", "yes", "true", "1"
        }
        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row.get("tags", "") or "")
            if tag.strip()
        }

        prepared.append({
            "index": index,
            "updated_dt": updated,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "zip": normalize_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": (row.get("source", "") or "").strip().lower(),
            "opted_out": opted_out,
            "tags": tags,
        })

    # Union-find ensures matching is transitive.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in email_owner:
                union(i, email_owner[row["email"]])
            else:
                email_owner[row["email"]] = i

        last_name_key = row["last_name"].casefold()
        if row["phone"] and last_name_key:
            key = (row["phone"], last_name_key)
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def pick(group, field, require_valid=False):
        candidates = [
            row for row in group
            if row[field] and (not require_valid or row[field])
        ]
        if not candidates:
            return ""
        candidates.sort(key=lambda row: (
            row["source"] != "manual",
            -row["updated_dt"].timestamp(),
            row["index"],
        ))
        return candidates[0][field]

    result = []
    for group in sorted(groups.values(), key=lambda g: min(r["index"] for r in g)):
        latest = max(row["updated_dt"] for row in group)
        result.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email"),
            "phone": pick(group, "phone"),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(set().union(*(row["tags"] for row in group)))),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return result
